sys_script_include.script:
var BuscaQuilometragemAtual = Class.create();

BuscaQuilometragemAtual.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getKm: function() {

        var veiculoId = this.getParameter('sysparm_veiculo_id');

        var record = new GlideRecord("x_894125_frota_veiculo");

        if (record.get(veiculoId)) {
            var veiculoKm = record.getValue("quilometragem_atual");
            return veiculoKm;
        }

        return "Não informado";
    },

    type: 'BuscaQuilometragemAtual'
});
